import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static long key(long r, long c) {
        return r * 1000003L + c;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        HashSet<Long> obs = new HashSet<>();
        int b = nextInt();
        for (int i = 0; i < b; i++) obs.add(key(nextInt(), nextInt()));
        HashMap<Long, int[]> tele = new HashMap<>();
        int k = nextInt();
        for (int i = 0; i < k; i++) {
            long from = key(nextInt(), nextInt());
            tele.put(from, new int[] {nextInt(), nextInt()});
        }
        int r = 0, c = 0;
        long steps = 1;
        HashSet<Long> seen = new HashSet<>();
        while (true) {
            if (!seen.add(key(r, c))) {
                System.out.println(-2); // the walk is deterministic, so a repeat loops forever
                return;
            }
            int[] to = tele.get(key(r, c));
            if (to != null) {
                r = to[0];
                c = to[1];
                steps++;
                continue;
            }
            if (r == n - 1 && c == m - 1) break;
            if (c + 1 < m && !obs.contains(key(r, c + 1))) c++;
            else if (r + 1 < n && !obs.contains(key(r + 1, c))) r++;
            else {
                System.out.println(-1);
                return;
            }
            steps++;
        }
        System.out.println(steps);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	type cell struct{ r, c int }
	obs := map[cell]bool{}
	b := nextInt()
	for i := 0; i < b; i++ {
		r := nextInt()
		obs[cell{r, nextInt()}] = true
	}
	tele := map[cell]cell{}
	k := nextInt()
	for i := 0; i < k; i++ {
		sr := nextInt()
		sc := nextInt()
		er := nextInt()
		tele[cell{sr, sc}] = cell{er, nextInt()}
	}
	p := cell{0, 0}
	steps := 1
	seen := map[cell]bool{}
	for {
		if seen[p] {
			fmt.Println(-2) // the walk is deterministic, so a repeat loops forever
			return
		}
		seen[p] = true
		if to, ok := tele[p]; ok {
			p = to
			steps++
			continue
		}
		if p == (cell{n - 1, m - 1}) {
			break
		}
		if right := (cell{p.r, p.c + 1}); p.c+1 < m && !obs[right] {
			p = right
		} else if down := (cell{p.r + 1, p.c}); p.r+1 < n && !obs[down] {
			p = down
		} else {
			fmt.Println(-1)
			return
		}
		steps++
	}
	fmt.Println(steps)
}
